import type { MainNavMenuItemProps } from "../main-nav-menu.types";

import { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { Menu } from "@components/menu";
import { Slot } from "@radix-ui/react-slot";

import { MainNavMenuClasses, StyledMainNavMenuItem } from "../main-nav-menu.styles";
import { useMainNavMenu } from "../hooks/use-main-nav-menu";

export const MainNavMenuItem = forwardRef(
  (
    {
      className,
      variant = "default",
      children,
      icon,
      hoverIcon,
      as = "a",
      asChild,
      ...props
    }: MainNavMenuItemProps,
    ref: React.ForwardedRef<HTMLAnchorElement>,
  ) => {
    const theme = useTheme(),
      rootClasses = clsx(MainNavMenuClasses.item, className),
      variantProp = variant === "default" ? "mainNavMenu" : variant;

    const context = useMainNavMenu();
    const mergedStyleSlots = { ...context?.styleSlots, ...props.styleSlots };

    const content = (
      <>
        {icon && (
          <span className={MainNavMenuClasses.itemIcon}>
            {hoverIcon ? (
              <span className={MainNavMenuClasses.iconSwap}>
                <span className={MainNavMenuClasses.iconSwapDefault}>{icon}</span>
                <span aria-hidden className={MainNavMenuClasses.iconSwapHover}>
                  {hoverIcon}
                </span>
              </span>
            ) : (
              icon
            )}
          </span>
        )}
        <span className={MainNavMenuClasses.itemLabel}>{children}</span>
      </>
    );

    return (
      <Menu.Item asChild>
        <StyledMainNavMenuItem
          ref={ref}
          as={asChild ? Slot : as}
          className={rootClasses}
          currentTheme={theme}
          styleSlots={mergedStyleSlots}
          variant={variantProp}
          {...props}
        >
          {asChild ? children : content}
        </StyledMainNavMenuItem>
      </Menu.Item>
    );
  },
);

MainNavMenuItem.displayName = "MainNavMenu.Item";
